-- Auto-generated from seed.sql — syncs `services` rows that already exist
-- live (matched by `id`) with the latest content: prices, descriptions,
-- images, etc. Safe to run on the live, already-seeded database.
--
-- Unlike seed.sql's INSERT IGNORE (which skips existing rows), this uses
-- ON DUPLICATE KEY UPDATE so existing rows are actually overwritten with the
-- new values. Rows with an id not yet present are inserted as new.
--
-- Does not touch service_categories, blog_posts, contacts, or any other
-- table — only `services`.
--
-- Import via phpMyAdmin -> SQL tab (or Import), same as install.sql/seed.sql.

ON DUPLICATE KEY UPDATE
  `category_id` = VALUES(`category_id`),
  `slug` = VALUES(`slug`),
  `name` = VALUES(`name`),
  `summary` = VALUES(`summary`),
  `bullets` = VALUES(`bullets`),
  `what_to_expect` = VALUES(`what_to_expect`),
  `ideal_for` = VALUES(`ideal_for`),
  `duration_minutes` = VALUES(`duration_minutes`),
  `price` = VALUES(`price`),
  `image` = VALUES(`image`),
  `sort_order` = VALUES(`sort_order`),
  `is_featured` = VALUES(`is_featured`),
  `is_active` = VALUES(`is_active`),
  `description` = VALUES(`description`);
